<script setup>
import { ChevronDown } from 'lucide-vue-next'
import { renderMarkdown } from '@/utils/markdown'
import { errorCategoryLabel } from '@/utils/errorCategories'
defineProps({ item: { type: Object, required: true } })
const answerText = value => Array.isArray(value) ? value.length ? value.join('、') : '未作答' : value === null || value === undefined || value === '' || value === '（未作答）' ? '未作答' : String(value)
const scoringLabels = { all_or_nothing: '全对得分', partial: '部分得分', partial_minus: '部分得分，错选扣分' }
</script>
<template>
  <details :class="['question-review', item.correct ? 'ok' : 'bad']">
    <summary><span class="result-badge">{{ item.correct ? '答对' : answerText(item.your_answer) === '未作答' ? '未作答' : '待巩固' }}</span><strong>第 {{ item.position }} 题</strong><span v-if="item.score_awarded != null" class="review-score">{{ item.score_awarded }} / {{ item.max_score }} 分</span><ChevronDown class="review-chevron" :size="17" /></summary>
    <div class="review-content"><div class="math review-stem" v-html="renderMarkdown(item.content || item.question_content || '')" /><div class="answer-comparison"><div><span>你的答案</span><strong>{{ answerText(item.your_answer) }}</strong></div><div><span>正确答案</span><strong>{{ answerText(item.correct_answer) }}</strong></div></div><p v-if="!item.correct && item.error_category" class="error-category">错因 · {{ errorCategoryLabel(item.error_category) }}</p><p v-if="item.scoring" class="scoring-note">多选计分：{{ scoringLabels[item.scoring] || item.scoring }} · 得分比例 {{ Math.round((item.partial_credit ?? (item.correct ? 1 : 0)) * 100) }}%</p><div v-if="item.analysis" class="review-analysis"><h3>题目解析</h3><div class="math" v-html="renderMarkdown(item.analysis)" /></div><aside v-if="item.selection_explanation || item.selection_reason"><strong>选题依据</strong><p>{{ item.selection_explanation?.evidence_summary || item.selection_reason }}</p></aside><slot /></div>
  </details>
</template>
